game_code = '<div style="font-family:sans-serif;display:flex;flex-direction:column;align-items:center;background:#1f2937;padding:15px;border-radius:20px;direction:rtl;"><div style="display:flex;justify-content:space-between;width:100%;max-width:500px;background:#111827;color:white;padding:15px;border-radius:15px;margin-bottom:15px;"><div><h3 style="margin:0;color:#10b981;">👤 اللاعب: ADAM_PRO</h3><p style="margin:5px 0 0 0;">⭐ المستوى: <span id="hero-level">1</span></p><p style="margin:5px 0 0 0;">💰 الأموال: <span id="hero-gold" style="color:#facc15;font-weight:bold;">$0</span></p></div><div style="text-align:left;border-right:2px solid #374151;padding-right:15px;"><h4 style="margin:0;color:#3b82f6;">📜 مهمة المدينة:</h4><p id="quest-text" style="margin:5px 0 0 0;font-size:13px;color:#9ca3af;">تصفية 3 من زعماء الشوارع!</p><p style="margin:5px 0 0 0;font-size:13px;color:#3b82f6;">التقدم: <span id="quest-progress">0</span> / 3</p></div></div><div style="position:relative;width:100%;max-width:500px;height:380px;background:#000;border-radius:20px;overflow:hidden;perspective:1200px;perspective-origin:50% 25%;"><div style="position:absolute;top:0;width:100%;height:35%;background:linear-gradient(to bottom,#030712,#0b1528);border-bottom:3px solid #1f3aa2;"></div><div style="position:absolute;bottom:-100px;width:100%;height:90%;background:repeating-linear-gradient(0deg,#1f2937 0px,#1f2937 40px,#111827 40px,#111827 80px);transform:rotateX(65deg);transform-origin:top;"><div style="position:absolute;left:50%;width:6px;height:100%;background:repeating-linear-gradient(to bottom,#facc15 0px,#facc15 40px,transparent 40px,transparent 80px);transform:translateX(-50%);opacity:0.6;"></div></div><div style="position:absolute;top:15px;width:80%;left:10%;background:#111;border-radius:6px;height:16px;"><div id="enemy-hp-bar" style="width:100%;background:linear-gradient(to right,#dc2626,#f87171);height:100%;border-radius:5px;transition:width 0.15s;"></div><span id="enemy-hp-text" style="position:absolute;width:100%;text-align:center;font-size:11px;color:white;font-weight:bold;top:0;">BOSS HP: 100/100</span></div><h3 id="enemy-name" style="position:absolute;top:36px;width:100%;text-align:center;color:#ef4444;margin:0;font-weight:bold;z-index:10;">🔥 المافيوزي الضخم بالمدينة</h3><div id="enemy-container" style="position:absolute;top:22%;left:50%;transform:translateX(-50%) translateZ(-200px);transition:transform 0.2s;z-index:4;"><div id="enemy-sprite" style="font-size:90px;user-select:none;">👹</div></div><div id="hero-container" style="position:absolute;bottom:30px;left:50%;transform:translateX(-50%) translateZ(120px);transition:transform 0.15s;z-index:6;"><div id="hero-sprite" style="font-size:85px;transform:scaleX(-1);user-select:none;">🥷</div></div><div id="damage-pop" style="position:absolute;color:#facc15;font-size:40px;font-weight:bold;display:none;z-index:20;left:45%;top:35%;">💥</div></div><div style="margin-top:15px;display:flex;gap:10px;width:100%;max-width:500px;"><button onclick="attack(30,\'combo\')" style="flex:1;background:#dc2626;color:white;border:none;padding:15px;border-radius:14px;font-size:16px;font-weight:bold;cursor:pointer;box-shadow:0 5px #7f1d1d;">⚔️ ضربة كومبو متتالية</button><button onclick="attack(60,\'special\')" style="flex:1;background:#eab308;color:white;border:none;padding:15px;border-radius:14px;font-size:16px;font-weight:bold;cursor:pointer;box-shadow:0 5px #713f12;">⚡ ضربة قاضية واقعية</button></div><div id="insta-ad" style="display:none;background-color:#111827;padding:15px;border-radius:15px;border-left:5px solid #E1306C;text-align:center;margin-top:15px;width:90%;"><p style="font-size:14px;margin:0;color:#e5e7eb;">📸 تابعنا في إنستغرام <strong style="color:#E1306C;">oughilas</strong> للجديد! 🚀</p><a href="https://instagram.com" target="_blank" style="background-color:#E1306C;color:white;padding:6px 12px;text-decoration:none;border-radius:15px;font-size:12px;display:inline-block;margin-top:5px;font-weight:bold;">المتابعة الآن</a></div><script>let heroLevel=1,heroGold=0,monstersDefeated=0,questTarget=3,enemyMaxHp=100,enemyHp=100,isAttacking=false;const monsters=[{name:"🔥 المافيوزي الضخم بالمدينة",sprite:"👹",hp:100,gold:150},{name:"🛸 الطائرة المسيرة المعادية",sprite:"🛸",hp:240,gold:350},{name:"🤖 المدرعة العسكرية القتالية",sprite:"🤖",hp:400,gold:800}];let currentMonsterIndex=0;function attack(maxDmg,type){if(enemyHp<=0||isAttacking)return;isAttacking=true;let dmg=Math.floor(Math.random()*20)+(maxDmg-10);enemyHp-=dmg;if(enemyHp<0)enemyHp=0;document.getElementById(\'enemy-hp-bar\').style.width=(enemyHp/enemyMaxHp)*100+\'%\';document.getElementById(\'enemy-hp-text\').innerText=\'BOSS HP: \'+enemyHp+\'/\'+enemyMaxHp;const hero=document.getElementById(\'hero-container\'),enemy=document.getElementById(\'enemy-container\'),pop=document.getElementById(\'damage-pop\');if(type===\'combo\'){hero.style.transform="translateX(-50%) translateZ(40px) translateY(-25px) scale(1.08)";enemy.style.transform="translateX(-50%) translateZ(-230px) rotateX(-12deg)";}else{hero.style.transform="translateX(-50%) translateZ(60px) translateY(-50px) scale(1.15)";enemy.style.transform="translateX(-50%) translateZ(-250px) rotateY(18deg)";}pop.innerText=\'💥 -$\'+dmg;pop.style.display=\'block\';setTimeout(()=>{hero.style.transform="translateX(-50%) translateZ(120px) translateY(0px) scale(1)";enemy.style.transform="translateX(-50%) translateZ(-200px)";pop.style.display=\'none\';isAttacking=false;if(enemyHp<=0)monsterDied();},250);}function monsterDied(){heroGold+=monsters[currentMonsterIndex].gold;monstersDefeated++;document.getElementById(\'hero-gold\').innerText=\'$\'+heroGold;if(monstersDefeated<=questTarget)document.getElementById(\'quest-progress\').innerText=monstersDefeated;if(monstersDefeated===questTarget){heroLevel++;document.getElementById(\'hero-level\').innerText=heroLevel;document.getElementById(\'insta-ad\').style.display=\'block\';}currentMonsterIndex=(currentMonsterIndex+1)%monsters.length;enemyMaxHp=monsters[currentMonsterIndex].hp+(heroLevel*40);enemyHp=enemyMaxHp;const sprite=document.getElementById(\'enemy-sprite\');sprite.style.opacity=\'0\';setTimeout(()=>{document.getElementById(\'enemy-name\').innerText=monsters[currentMonsterIndex].name;sprite.innerText=monsters[currentMonsterIndex].sprite;sprite.style.opacity=\'1\';document.getElementById(\'enemy-hp-bar\').style.width=\'100%\';document.getElementById(\'enemy-hp-text\').innerText=\'BOSS HP: \'+enemyHp+\'/\'+enemyMaxHp;},400);}</script></div>'

